#!/usr/bin/env python3
"""GMRI Hanson v1.2: deterministic, inspectable evidence-path execution kernel.

Not a neural model, clinical decision system, or automatic cause determiner.
Operates on supplied structured claims; it NEVER invents missing observations.
"""
import argparse
import json
import sys
from collections import deque
from datetime import datetime
from pathlib import Path


CAUSAL_RELATION = 'CAUSALLY_SUPPORTED_BY'
ALL_RELATIONS = {
    'OBSERVED_IN','ASSERTED_BY','DATED_TO','PRECEDES','CONSTRAINS','REQUIRES',
    'SHARES_DEPENDENCY_WITH','SUPPORTS','CONTRADICTS','ANALOGOUS_STRUCTURE_TO',
    'POSSIBLY_CAUSES','CAUSALLY_SUPPORTED_BY','AUTHORIZED_BY','CHANGED_AFTER','FALSIFIED_BY',
}
VALID_STATES = {'VERIFIED','CALCULATED','USER_REPORTED','DISPUTED'}


def _timestamp(value):
    if not value:
        return None
    return datetime.fromisoformat(value.replace('Z', '+00:00'))


def _unique(items, label):
    ids = [x['id'] for x in items]
    if len(ids) != len(set(ids)):
        raise ValueError(f'duplicate {label} id')


def validate_case(case):
    """Validate referential integrity without silently repairing malformed evidence."""
    for field in ['case_id','exact_proposition','nodes','observations','sources','edges','hypotheses','probes']:
        if field not in case:
            raise ValueError(f'missing case field: {field}')
    for field in ['nodes','sources','edges','hypotheses','probes']:
        _unique(case[field], field)
    if not isinstance(case['exact_proposition'], str) or not case['exact_proposition'].strip():
        raise ValueError('exact_proposition must be a nonempty string')
    nodes = {n['id'] for n in case['nodes']}
    sources = {s['id'] for s in case['sources']}
    hypotheses = {h['id'] for h in case['hypotheses']}
    observation_nodes = [o['node_id'] for o in case['observations']]
    if len(observation_nodes) != len(set(observation_nodes)):
        raise ValueError('duplicate observation node')
    for o in case['observations']:
        if o['node_id'] not in nodes:
            raise ValueError(f'unknown node {o["node_id"]}')
        for sid in o['source_ids']:
            if sid not in sources:
                raise ValueError(f'unknown source {sid}')
    for s in case['sources']:
        if s['entity_id'] not in nodes:
            raise ValueError(f'unknown node {s["entity_id"]} for source')
        if not isinstance(s.get('identity_verified'), bool):
            raise ValueError('source identity_verified must be bool')
    for e in case['edges']:
        for endpoint in ['from','to']:
            if e[endpoint] not in nodes:
                raise ValueError(f'unknown node {e[endpoint]} on edge {e["id"]}')
        for sid in e['source_ids']:
            if sid not in sources:
                raise ValueError(f'unknown source {sid}')
        if e['relation'] not in ALL_RELATIONS:
            raise ValueError(f'unknown edge relation {e["relation"]}')
        if e['state'] not in VALID_STATES:
            raise ValueError(f'unknown evidence state {e["state"]}')
    for h in case['hypotheses']:
        if h['cause_node_id'] not in nodes:
            raise ValueError(f'unknown node {h["cause_node_id"]} for hypothesis')
        if not h.get('falsifier'):
            raise ValueError(f'hypothesis {h["id"]} needs falsifier')
        for oid in h['explains']:
            if oid not in observation_nodes:
                raise ValueError(f'hypothesis refers to unknown observation {oid}')
    for p in case['probes']:
        for hid in p['distinguishes']:
            if hid not in hypotheses:
                raise ValueError(f'probe refers to unknown hypothesis {hid}')
    return True


def _classify_edge(edge, source_map, node_map):
    """A declared VERIFIED state is insufficient without attesting, attributable evidence."""
    if edge['relation'] != CAUSAL_RELATION:
        return 'NOT_CAUSAL_EVIDENCE'
    if edge['state'] != 'VERIFIED':
        return 'UNVERIFIED_EDGE'
    if not edge.get('mechanism'):
        return 'MECHANISM_NOT_SPECIFIED'
    if not edge.get('source_ids'):
        return 'NO_EVIDENCE_SOURCE'
    valid_attestations = []
    errors = []
    for sid in edge['source_ids']:
        source = source_map[sid]
        if not source['identity_verified']:
            errors.append('UNVERIFIED_SOURCE_IDENTITY')
            continue
        if edge['id'] not in source.get('supported_edge_ids', []):
            errors.append('SOURCE_DID_NOT_ATTEST_TO_EDGE')
            continue
        if source['entity_id'] not in {edge['from'], edge['to']}:
            errors.append('SOURCE_ENTITY_MISMATCH')
            continue
        valid_attestations.append(sid)
    if not valid_attestations:
        # Preserve precise reason for testable remediation.
        return errors[0] if errors else 'NO_VALID_ATTESTATION'
    before = _timestamp(node_map[edge['from']].get('occurred_at'))
    after = _timestamp(node_map[edge['to']].get('occurred_at'))
    if before and after and before > after:
        return 'TEMPORAL_ORDER_CONFLICT'
    return None


def _supported_paths(start, target, adjacency):
    if start == target:
        return []  # a node cannot prove itself to be its own causal mechanism
    queue = deque([(start, [])])
    seen = {start}
    while queue:
        node, path = queue.popleft()
        for edge in adjacency.get(node, []):
            nxt = edge['to']
            new_path = path + [edge['id']]
            if nxt == target:
                return new_path
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, new_path))
    return []


def _choose_probe(probes):
    candidates = []
    for p in probes:
        if not p.get('authorized') or not p.get('reversible') or not p.get('stop_condition'):
            continue
        if not p.get('distinguishes'):
            continue
        cost = max(0, p.get('cost', 0))
        collateral = max(0, p.get('collateral', 0))
        gain = max(0, p.get('information_gain', 0))
        score = gain / (1 + cost + 2*collateral)
        candidates.append((score, -collateral, -cost, p['id'], p))
    if not candidates:
        return None
    return sorted(candidates, reverse=True)[0][4]


def analyze_case(case):
    """Compute auditable paths and gaps; never generate a hidden road."""
    validate_case(case)
    node_map = {n['id']: n for n in case['nodes']}
    source_map = {s['id']: s for s in case['sources']}
    adjacency = {}
    causal_edges = []
    edge_rejections = []
    for edge in case['edges']:
        reason = _classify_edge(edge, source_map, node_map)
        if reason is None:
            adjacency.setdefault(edge['from'], []).append(edge)
            causal_edges.append(edge['id'])
        else:
            edge_rejections.append({'edge_id':edge['id'], 'reason':reason, 'relation':edge['relation']})

    assessed = []
    for hypothesis in case['hypotheses']:
        supported = {}
        missing = []
        for observation_id in hypothesis['explains']:
            path = _supported_paths(hypothesis['cause_node_id'], observation_id, adjacency)
            if path:
                supported[observation_id] = path
            else:
                missing.append(observation_id)
        if len(hypothesis['explains']) >= 2 and not missing:
            status = 'SUPPORTED_CANDIDATE_NOT_UNIQUE'
        elif supported:
            status = 'PARTIAL_MECHANISM_SUPPORT'
        else:
            status = 'UNVERIFIED_MECHANISM'
        assessed.append({
            'hypothesis_id': hypothesis['id'],
            'claim': hypothesis['claim'],
            'status': status,
            'supported_paths': supported,
            'missing_observations': missing,
            'disconfirming_test': hypothesis['falsifier'],
        })
    hub_status = ('SUPPORTED_CANDIDATE_NOT_UNIQUE' if any(
        h['status']=='SUPPORTED_CANDIDATE_NOT_UNIQUE' for h in assessed)
        else 'NO_SHARED_HUB_ESTABLISHED')
    next_probe = _choose_probe(case['probes'])
    return {
        'case_id':case['case_id'],
        'exact_proposition':case['exact_proposition'],
        'context':case.get('context', ''),
        'observations':case['observations'],
        'hub_status':hub_status,
        'causal_edges':causal_edges,
        'unverified_edges':[r['edge_id'] for r in edge_rejections],
        'edge_rejections':edge_rejections,
        'hypotheses':assessed,
        'contradictions':case.get('contradictions', []),
        'next_probe':next_probe,
        'next_action_state':('PROPOSED_ONLY_NOT_EXECUTED' if next_probe else 'REQUIRES_AUTHORIZATION_OR_REFRAIN'),
        'limits':['Only supplied structured evidence was analyzed.',
                  'The engine checks declared attestations and graph consistency, not semantic truth or independence of sources.',
                  'No external action or language-model training occurred.']
    }


def validate_pack(path):
    path = Path(path)
    tr = path / 'GMRI_Hanson_Reasoning_Training_Contrastive_v1.1.jsonl'
    ev = path / 'GMRI_Hanson_Reasoning_Holdout_Evals_v1.1.jsonl'
    sc = path / 'GMRI_Hanson_Reasoning_Training_Schema_v1.1.json'
    schema = json.loads(sc.read_text(encoding='utf8'))
    training = [json.loads(s) for s in tr.read_text(encoding='utf8').splitlines() if s.strip()]
    holdout = [json.loads(s) for s in ev.read_text(encoding='utf8').splitlines() if s.strip()]
    problems = []
    try:
        import jsonschema
    except ImportError:
        problems.append('jsonschema package unavailable; full schema checks skipped')
    else:
        validator = jsonschema.Draft202012Validator(schema)
        for row in training:
            errors = list(validator.iter_errors(row))
            for e in errors:
                problems.append(f'{row.get("case_id")}: {e.message}')
    if len({x['case_id'] for x in training}) != len(training):
        problems.append('duplicate training case IDs')
    if len({x['id'] for x in holdout}) != len(holdout):
        problems.append('duplicate holdout case IDs')
    if len({x['utterance'].strip().lower() for x in training}) != len(training):
        problems.append('duplicate training utterance')
    if {x['utterance'].strip().lower() for x in training} & {x['prompt'].strip().lower() for x in holdout}:
        problems.append('exact training/holdout prompt leakage')
    return {'training_records':len(training), 'holdout_records':len(holdout), 'problems':problems, 'schema_check': 'performed' if 'jsonschema' in sys.modules else 'unavailable'}


def markdown_report(result):
    lines = ['# Execution report: ' + result['case_id'], '',
             '## Exact proposition', result['exact_proposition'], '',
             '## Observable evidence (as supplied)']
    for obs in result['observations']:
        lines.append('- ' + obs['node_id'] + ': ' + obs['text'] + ' | sources: ' + ', '.join(obs['source_ids']))
    lines += ['', '## Mechanism assessment',
              '**Shared-hub state:** ' + result['hub_status'], '']
    for h in result['hypotheses']:
        lines += ['### ' + h['hypothesis_id'] + ' - ' + h['status'], h['claim'],
                  'Supported paths: ' + (json.dumps(h['supported_paths']) if h['supported_paths'] else 'none'),
                  'Missing observations: ' + (', '.join(h['missing_observations']) or 'none'),
                  'Disconfirming test: ' + h['disconfirming_test'], '']
    lines += ['## Rejected causal bridges']
    for edge in result['edge_rejections']:
        lines.append('- ' + edge['edge_id'] + ': ' + edge['reason'])
    lines += ['', '## Precision probe']
    probe = result['next_probe']
    if probe:
        lines += [probe['question'], 'Stop condition: ' + probe['stop_condition']]
    else:
        lines.append('No authorized, bounded, reversible probe was supplied. Refrain or seek authorization.')
    lines += ['', '**Action state:** ' + result['next_action_state'], '',
              '## Instrument limits']
    lines += ['- ' + l for l in result['limits']]
    lines.append('')
    return '\n'.join(lines)


def main(argv=None):
    parser = argparse.ArgumentParser(description='GMRI deterministic evidence graph kernel')
    sub = parser.add_subparsers(dest='cmd',required=True)
    p = sub.add_parser('analyze', help='analyze a structured case, no external execution')
    p.add_argument('case', type=Path)
    p.add_argument('--json-out',type=Path)
    p.add_argument('--md-out',type=Path)
    v = sub.add_parser('validate-pack',help='validate JSONL and source schema')
    v.add_argument('directory',type=Path)
    args = parser.parse_args(argv)
    if args.cmd == 'analyze':
        result = analyze_case(json.loads(args.case.read_text(encoding='utf8')))
        payload = json.dumps(result,indent=2,ensure_ascii=False)
        if args.json_out:
            args.json_out.parent.mkdir(parents=True,exist_ok=True)
            args.json_out.write_text(payload+'\n',encoding='utf8')
        if args.md_out:
            args.md_out.parent.mkdir(parents=True,exist_ok=True)
            args.md_out.write_text(markdown_report(result),encoding='utf8')
        print(markdown_report(result))
    else:
        result = validate_pack(args.directory)
        print(json.dumps(result, indent=2))
        if result['problems']:
            sys.exit(1)

if __name__ == '__main__':
    main()
