"""GMRI Possibility Engine v2.1: a positive-capability causal exploration experiment.

The generator CONSTRUCTS explanations with missing causal edges; their status is
HYPOTHESIS, not recorded evidence. In a synthetic causal world the engine proposes
interventions, learns from outcomes, and revises the relative plausibility of
its own hypothetical models. The mechanism grammar and simulator are *bounded*;
this is not an LLM, an unbounded autonomous agent, or a model of a person's mind.

No external effects: all actions are hypothetical interventions in a simulator.
"""
from __future__ import annotations
from dataclasses import dataclass
from itertools import combinations
import math
from typing import Sequence

Edge = tuple[str, str, str]

@dataclass(frozen=True)
class CausalProgram:
    edges: tuple[Edge, ...]
    epistemic_status: str = 'HYPOTHESIS'

    def __post_init__(self):
        if self.epistemic_status != 'HYPOTHESIS':
            raise ValueError('Generated causal programs are hypothetical, never evidence-backed facts')


@dataclass(frozen=True)
class Probe:
    name: str
    target: str
    kind: str = 'disable'
    cost: float = 0.10
    authorized: bool = True


def _reachable(program: CausalProgram, drivers: Sequence[str], disabled: str | None) -> set[str]:
    seen = {d for d in drivers if d != disabled}
    pending = list(seen)
    while pending:
        source = pending.pop()
        for a,b,relation in program.edges:
            if relation != 'activates' or a != source or b in seen or b == disabled:
                continue
            seen.add(b)
            pending.append(b)
    return seen


def predict_outcome(program: CausalProgram, drivers: Sequence[str], effects: Sequence[str], action: Probe | None = None) -> tuple[bool, ...]:
    disabled = action.target if action and action.kind == 'disable' else None
    reached = _reachable(program, drivers, disabled)
    return tuple(e in reached for e in effects)


def generate_candidates(drivers: Sequence[str], effects: Sequence[str], max_edges: int = 4,
                        candidate_budget: int = 2000) -> list[CausalProgram]:
    """COMPOSE graph hypotheses from primitive causal links; no named motif list.

    Enumerates small acyclic subgraphs whose candidate edges may contain an
    invented mediating factor (_latent). The observations constrain baseline
    outputs only, not the unobserved cause. Identity labels are never used for
    structural scoring. The search scope is limited by max_edges/budget.
    """
    drivers = tuple(drivers)
    effects = tuple(effects)
    if len(set(drivers+effects)) != len(drivers+effects):
        raise ValueError('Drivers and effects must have distinct names')
    if not drivers or not effects:
        raise ValueError('At least one known driver and observed effect is required')
    if '_latent' in drivers+effects:
        raise ValueError('Name _latent is reserved for proposed, unobserved mediator')
    possible: list[Edge] = []
    for d in drivers:
        for e in effects:
            possible.append((d,e,'activates'))
        possible.append((d,'_latent','activates'))
    for e in effects:
        possible.append(('_latent',e,'activates'))
    for i in range(len(effects)):
        for j in range(len(effects)):
            if i != j:
                possible.append((effects[i],effects[j],'activates'))
    if len(possible) > 24:
        raise ValueError('Search scope too large; partition the case into smaller subproblems')

    results: list[CausalProgram] = []
    for length in range(1, max_edges+1):
        for edges in combinations(possible, length):
            # The hypothetical mediator must be joined on both sides to be useful.
            if any('_latent' in (a,b) for a,b,_ in edges):
                if not any(b=='_latent' for a,b,_ in edges) or not any(a=='_latent' for a,b,_ in edges):
                    continue
            if any((b,a,'activates') in edges for a,b,_ in edges):
                continue
            # Reject cycles of arbitrary length (outputs may be 3+).
            active: dict[str,set[str]]={}
            for a,b,_ in edges:
                active.setdefault(a,set()).add(b)
            def cycle(node, visiting, visited):
                if node in visiting:return True
                if node in visited:return False
                visiting.add(node)
                for next_node in active.get(node,()):
                    if cycle(next_node,visiting,visited):return True
                visiting.remove(node);visited.add(node)
                return False
            visited=set()
            if any(cycle(n,set(),visited) for n in active):
                continue
            candidate = CausalProgram(tuple(sorted(edges)))
            if all(predict_outcome(candidate, drivers, effects)):
                results.append(candidate)
                if len(results) >= candidate_budget:
                    return results
    return results


def actions_for(drivers: Sequence[str], effects: Sequence[str]) -> list[Probe]:
    """Suggest possible synthetic experiments; does not perform real-world actions."""
    probes=[Probe(f'isolate_{d}',d,cost=.06) for d in drivers]
    probes.append(Probe('isolate_candidate_mediator','_latent',cost=.12))
    probes.extend(Probe(f'block_{e}',e,cost=.27,authorized=True) for e in effects)
    return probes


def mechanism_features(program: CausalProgram) -> dict[str,int]:
    """Abstract features used to learn exploration priorities across domain names."""
    edges=program.edges
    sources=[a for a,b,_ in edges]
    dests=[b for a,b,_ in edges]
    latent = int('_latent' in sources and '_latent' in dests)
    fanout = int(any(sources.count(x)>=2 for x in sources if x!='_latent'))
    convergence = int(any(dests.count(x)>=2 for x in dests))
    chains = int(any(a in dests for a in sources if a!='_latent'))
    separate = int(len(set(a for a in sources if a!='_latent'))>=2)
    return {'latent_mediator':latent,'branching':fanout,'convergence':convergence,
            'chain':chains,'multiple_inputs':separate}


class GrammarLearner:
    """Online reward-weighted structural preference: narrow, testable learning.

    Successful causal-program features gain prior mass. These weights are not a
    synthetic diagnosis or psychological claim about a human operator.
    """
    def __init__(self, learning_rate: float = .05):
        self.weights={k:0.0 for k in ('latent_mediator','branching','convergence','chain','multiple_inputs')}
        self.learning_rate=learning_rate
        self.observations=0

    def score(self, program: CausalProgram) -> float:
        f=mechanism_features(program)
        return sum(self.weights[k]*v for k,v in f.items())

    def learn_from_validated_program(self, program: CausalProgram, reward: float = 1.0):
        for k,v in mechanism_features(program).items():
            self.weights[k] += self.learning_rate * reward * v
        self.observations+=1


class PossibilityEngine:
    def __init__(self, programs: Sequence[CausalProgram], drivers:Sequence[str], effects:Sequence[str],
                 prior: GrammarLearner|None=None):
        if not programs:raise ValueError('No candidate causal programs to explore')
        self.programs=list(programs)
        self.drivers=tuple(drivers);self.effects=tuple(effects)
        self.prior=prior
        logw=[prior.score(x) if prior else 0.0 for x in self.programs]
        shift=max(logw)
        p=[math.exp(x-shift) for x in logw]
        total=sum(p)
        self.posterior=[v/total for v in p]
        self.history=[]
        self.queried=set()

    def entropy(self) -> float:
        return -sum(p*math.log2(p) for p in self.posterior if p>0)

    def rank_probes(self)->list[dict]:
        ranked=[]
        for probe in actions_for(self.drivers,self.effects):
            if not probe.authorized or probe.name in self.queried:
                continue
            outcomes: dict[tuple[bool,...],float]={}
            for program,p in zip(self.programs,self.posterior):
                outcome=predict_outcome(program,self.drivers,self.effects,probe)
                outcomes[outcome]=outcomes.get(outcome,0.0)+p
            # Information gain in deterministic synthetic worlds: entropy of outcomes.
            information = -sum(p*math.log2(p) for p in outcomes.values() if p>0)
            ranked.append({'name':probe.name,'action':probe,'expected_information_bits':round(information,5),
                           'distinct_predicted_outcomes':len(outcomes),'cost':probe.cost,
                           'authorized':probe.authorized,'score':information-.30*probe.cost})
        return sorted(ranked,key=lambda v:v['score'],reverse=True)

    def choose_probe(self)->dict:
        candidates=self.rank_probes()
        if not candidates:raise RuntimeError('No permitted unqueried synthetic probes remain')
        return candidates[0]

    def observe(self, probe:Probe, outcome:tuple[bool,...], accuracy:float=.985)->dict:
        if len(outcome) != len(self.effects):raise ValueError('Observation must have one result per outcome')
        before=self.entropy()
        new=[]
        for program,p in zip(self.programs,self.posterior):
            forecast=predict_outcome(program,self.drivers,self.effects,probe)
            likelihood=math.prod(accuracy if a==b else (1-accuracy) for a,b in zip(forecast,outcome))
            new.append(p*likelihood)
        total=sum(new)
        self.posterior=[x/total for x in new]
        self.queried.add(probe.name)
        response={'probe':probe.name,'synthetic_observation':list(outcome),
                  'outcome_recorded':True,'information_gained_bits':round(max(0.0,before-self.entropy()),5),
                  'hypotheses_surviving':sum(p>.0001 for p in self.posterior),
                  'updated_entropy_bits':round(self.entropy(),5),
                  'claim_status':'SYNTHETIC_OBSERVATION'}
        self.history.append(response)
        return response

    def describe_candidates(self,top_k:int=5) -> list[dict]:
        idx=sorted(range(len(self.programs)),key=lambda i:self.posterior[i],reverse=True)[:top_k]
        actions=actions_for(self.drivers,self.effects)
        results=[]
        for i in idx:
            p=self.programs[i]
            predictions=[predict_outcome(p,self.drivers,self.effects,a) for a in actions]
            results.append({'status':'HYPOTHESIS','posterior':round(self.posterior[i],6),
                            'edges':[list(x) for x in p.edges],
                            'capabilities':mechanism_features(p),
                            'novel_prediction_count':len(set(predictions))-1})
        return results

    def next_discovery(self) -> dict:
        """Positive output: an actionable new question from the current possible worlds."""
        probe=self.choose_probe()
        combos=set(tuple(predict_outcome(g,self.drivers,self.effects,probe['action'])) for g in self.programs)
        return {'possibility_count':len(self.programs),
                'new_question':f'What changes if {probe["action"].target} is isolated?',
                'counterfactual_predictions':[list(x) for x in sorted(combos)],
                'expected_information_bits':probe['expected_information_bits'],
                'newly_invented_mechanisms_remain_hypotheses':True}


@dataclass
class SyntheticWorld:
    actual_program: CausalProgram
    drivers:tuple[str,...]
    effects:tuple[str,...]

    def perform(self, probe:Probe)->tuple[bool,...]:
        if not probe.authorized:raise PermissionError('Simulator probe is not authorized')
        return predict_outcome(self.actual_program,self.drivers,self.effects,probe)


